create table if not exists public.womens_provincial_founders_leads (id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now(),full_name text not null,email text not null,cellphone text not null,province text not null check (province in ('Eastern Cape','Free State','Gauteng','KwaZulu-Natal','Limpopo','Mpumalanga','Northern Cape','North West','Western Cape')),purchase_type text not null check (purchase_type in ('individual','group')),contribution_amount numeric(10,2) not null check (contribution_amount in (105.00,105.56,950.00)),group_size integer not null default 1 check (group_size between 1 and 9),group_members jsonb not null default '[]'::jsonb,payment_status text not null default 'pending' check (payment_status in ('pending','paid','failed','refunded','review')),payment_reference text unique,payment_provider text,payment_confirmed_at timestamptz,source_host text,source_path text,privacy_consent boolean not null default false check (privacy_consent=true),marketing_consent boolean not null default false,notes text); create index if not exists womens_founders_province_status_idx on public.womens_provincial_founders_leads(province,payment_status); create index if not exists womens_founders_created_idx on public.womens_provincial_founders_leads(created_at desc); alter table public.womens_provincial_founders_leads enable row level security; revoke all on public.womens_provincial_founders_leads from anon,authenticated; grant select,insert,update,delete on public.womens_provincial_founders_leads to service_role;